#!/usr/bin/env python3
"""Full German per-passage gist for The Night Market."""
import json, os
OUT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "content", "gist", "the-night-market", "de.json")
G = {
 2: "Du ziehst das Rollgitter hoch, zündest die Brenner unter dem großen Topf an, hängst die zwei roten Laternen auf und wischst die Theke ab. Im hinteren Regal bleibt ein Platz leer. Rings um dich erwacht der Markt: Stimmen, Rauch, der Geruch von heißem Öl und Knoblauch.",
 3: "Du rufst die Tante an. Ihre Stimme ist müde, aber klar: „Probier die Brühe, bevor du sie verkaufst. Kauf beim alten Han, nicht beim billigen Wagen. Und stell eine Schale für Herrn Behn beiseite.“ Sie legt auf, vor Schmerz, bevor du mehr fragen kannst.",
 4: "In der Kasse liegt ein Zettel in der Handschrift der Tante: die Summe, die du bis zum Morgengrauen erreichen musst. Eine große Zahl, und eine Schale bringt nur ein paar Münzen: Es braucht eine ganze, volle Nacht, um dorthin zu kommen.",
 5: "Die Teefrau vom Stand 25, seit Jahren dort, beugt sich freundlich herüber: „Also du bist es heute Nacht. Die Hand deiner Tante, wie schlimm ist es?“ Sie sieht deine leere Theke und deine nervösen Hände und lächelt: „Keine Sorge. Ich behalte dich im Auge.“",
 7: "Du fragst, wer Herr Behn ist. Ein Schweigen. „Ein alter Freund“, sagt die Tante schließlich. „Er kam jeden Abend, dann hörte er auf. Heb ihm nur seine Schale auf. Bitte.“ In ihrer Stimme liegt etwas, das du nicht deuten kannst.",
 8: "Du rechnest nach: Eine Schale bringt ein paar Münzen, die Summe braucht Hunderte — eine ganze Nacht ohne Pause, ohne etwas zu verschwenden. Es geht; die Tante schafft es jede Saison. Doch sie ist schnell und sicher, und du bist beides noch nicht.",
 9: "Die Teefrau erklärt dir die Nacht: „Voll gegen neun, wieder voll um Mitternacht. Fairer Preis, sei flink, verschwende nichts.“ Dann leiser: „Herr Sould kommt vorbei. Er bietet Hilfe an — ein Darlehen, ein Wort an einen Rivalen. Sag Nein. Seine Hilfe ist ein Haken.“",
 10: "Das Schweinefleisch vom alten Han ist rosig und frisch, sein Gemüse knackig. Du packst es in die Kühlbox. Es kostete mehr als dir lieb — aber der Unterschied wird schmecken, und die Kunden merken ihn. Gutes Essen ist, wie die Tante diese Ecke seit dreißig Jahren hält.",
 11: "Die billige Ware kostet die Hälfte, also trägst du sie zum Stand. Doch das Schweinefleisch riecht fragwürdig und das Gemüse wird schon weich. Du hast gespart — vielleicht am falschen Ende. Eine schlechte Schale ist teuer: ein verlorener Kunde, und alle, denen er es erzählt.",
 12: "Du kaufst etwas Gutes und etwas Billiges, zur Absicherung. Es wirkt wie der sichere Mittelweg. Doch die Hälfte deiner Schalen bleibt hinter dem Besten der Tante zurück, und eine einzige schwache Schale zur falschen Zeit kann eine ganze Menge umstimmen. Du musst achten, welche Ware in welche Schale kommt.",
 14: "Du dankst ihr. „An dieser Ecke passen wir aufeinander auf“, sagt sie. „Deine Tante hat das öfter für mich getan, als ich zählen kann.“ Zu wissen, dass du heute Nacht nicht allein bist, tut gut: Ein freundliches Gesicht ist viel wert, wenn die Menge kommt.",
 15: "Ein Mann im sauberen Mantel hält an, lächelnd wie ein alter Freund: „Du musst Sims Familie sein. Schlimme Sache, ihre Hand. Keine Sorge — ich kümmere mich um diesen Markt. Was immer du heute Nacht brauchst, komm direkt zu Herrn Sould.“ Sein Lächeln ist warm. Seine Augen, bemerkst du, nicht.",
 16: "Der Stand ist endlich bereit: rote Laternen, dampfende Brühe, gestapelte Schalen. In der Passage strömt die Menge jetzt dicht vorbei, durch Rauch, Lärm und den Geruch von hundert Küchen. Manche haben Hunger. Manche halten hier — wenn du schnell bist und das Essen gut.",
 17: "Du wirfst das Schlimmste der billigen Ware weg. Es schmerzt, Geld wegzuwerfen, das du schon ausgegeben hast — aber eine schlechte Schale kostet weit mehr. Du behältst, was noch gut aussieht und riecht, der Rest geht. Lieber eine kleinere Nacht als ein befleckter Name. Die Tante hätte es genauso gemacht.",
 18: "Eine Schale wartet nun im hinteren Regal, voll und warm, auf einen Mann, der vielleicht nie kommt. Da oben wirkt sie klein, ein wenig traurig — aber auch richtig. Es ist der Stand der Tante, und so war er immer. Heute Nacht hältst du mehr als ein Geschäft am Leben.",
 19: "Der große Brenner klickt und klickt, ohne zu zünden — das Gas zischt, keine Flamme. Ohne ihn bleibt die Brühe kalt, und kalte Brühe verkauft niemandem etwas. Deine Hände zittern ein wenig; nicht der Anfang, den du wolltest. Aber jeder Koch hat schon mit einem störrischen Brenner gekämpft.",
 20: "Du probierst die Brühe: zuerst das Salz, dann der Ingwer, dann ein tiefer, warmer Ton darunter, den du nicht benennen kannst. Das ist der Geschmack, für den man den ganzen Markt quert — dreißig Jahre Sorgfalt in einem Löffel. Koch sie, wie sie es dir zeigte, und die Brühe verkauft die Hälfte für dich.",
 21: "Die Tante kommt immer wieder auf die Summe zurück: „Verlier die Ecke nicht. Meine Mutter hatte sie vor mir — dreißig Jahre.“ Unter ihren Worten läuft Angst. Du beruhigst sie, ohne selbst sicher zu sein. Aber sie muss die Hand schonen, und sich am Telefon zu sorgen hilft keiner von euch.",
 22: "Die Stammgäste kennen die Schale der Tante auswendig — Größe, Hitze, Preis, das genaue Gleichgewicht. Ist deine anders, spüren sie es beim ersten Schluck. Du kannst heute Nacht nicht die Tante sein. Aber du kannst ihre Schale auf ihre Art machen und sie für sie sprechen lassen.",
 23: "Deine allererste große Bestellung: eine sechsköpfige Familie, alle durcheinander redend. Sechs Schalen, mit Änderungen für die Kinder. Viel, um es in deiner ersten Stunde zu behalten. Gut gemacht, kommen sie die ganze Saison; verpatzt, ist deine erste Geschichte der Nacht eine schlechte.",
 24: "Ein kleines Kind zählt Münzen zu einem sorgsamen Häufchen. Ihm fehlt eine für eine Schale. Es sieht zu dir, dann zu den Münzen, dann wieder zu dir, ohne ein Wort. Ein winziger Moment — aber wie du antwortest, ist genau das, woran sich ein Markt bei einem Stand erinnert.",
 26: "Bestellungen fliegen von allen Seiten: „Zwei Schalen!“ „Mehr Teigtaschen!“ „Wie lange dauert's?“ Du kannst sie unmöglich alle behalten. Du brauchst ein System, und schnell: der Reihe nach annehmen, jede zurücksagen, die Schlange in Bewegung halten. Panik verliert Schalen, Ruhe hält sie. Du wählst die Ruhe.",
 27: "„Wo ist Sim?“ fragt ein Stammgast und sucht ihr Gesicht. „Geht es ihr gut?“ Du kannst die Wahrheit sagen — ihre Hand, die Verbrennung, du heute Nacht — oder lächeln, servieren, es leicht halten. Man kommt fürs Essen, aber auch für sie. Deine Antwort sagt, was für ein Stand das heute Nacht ist.",
 28: "Heiße Brühe spritzt auf deine Hand und du keuchst. Es brennt, scharf und plötzlich — genau so hat sich die Tante verletzt, denkst du unwillkürlich. Einen Moment füllt der Schmerz die ganze Welt. Dann atmest du und wickelst sie in ein nasses Tuch. Der Stand hält nicht wegen einer Verbrennung an.",
 29: "Der Dämpfer zischt und verstummt — trocken, die Teigtaschen halb gar. Du rettest ihn gerade noch: eine Minute mehr, und sie wären verbrannt, und der Geruch von Verbranntem leert eine Theke schneller als alles. Du füllst schnell und sorgfältig nach. Ein kleiner Erfolg — aber sie summieren sich.",
 30: "Ein ruhigerer Abschnitt. Du wischst, füllst Schalen auf, richtest die Theke. In der Stille schweift der Sinn ab — zur Summe, zum leeren Hocker, zur besorgten Stimme der Tante. Dann taucht ein Kunde auf und du bist wieder drin. Aber in den ruhigen Abschnitten denkt man, und Denken hält eine ganze Nacht durch.",
 31: "Die ersten echten Kunden erreichen die Theke, hungrig und zahlungsbereit. Also — was verlangst du? Die Tante hat einen Preis, fair und fest, den alle Stammgäste kennen. Du kannst ihn halten, für Touristen höher gehen, oder niedrig bleiben und auf mehr Verkäufe hoffen. Die Zahl heute Nacht ist eine Art Versprechen.",
 32: "Du setzt einen fairen Preis — nicht zu hoch, nicht zu niedrig. Es ist ehrlich, und Ehrliches lässt sich leicht vertreten. Die Kunden zahlen ohne Murren; niemand streitet über fair. Du verdienst nicht das Meiste pro Schale, aber die Leute kommen wieder, und ein voller Stand schlägt einen gierigen jedes Mal.",
 33: "Du schlägst beim Preis auf. Touristen merken nichts, und mehr pro Schale heißt weniger Schalen bis zur Summe — verlockend. Doch das Gerücht reist schnell: Erwischen dich die Stammgäste beim Verdoppeln, fühlen sie sich betrogen, und ein Stand, der betrügt, hält keine Ecke dreißig Jahre.",
 34: "Du nimmst den üblichen Preis der Tante, auf den Cent genau. Der erste Stammgast bemerkt es, und etwas in seinem Gesicht entspannt sich: „Wie immer“, sagt er zufrieden. Es sagt ihnen auf kleine Weise, dass sie noch da ist. Manchmal ist die sicherste Wahl auch einfach die richtige.",
 35: "Du schöpfst die Brühe, gibst die Teigtaschen hinein und reichst die ersten Schalen über die Theke. Dampf steigt in die kalte Nacht; Hände nehmen die Schalen; Münzen fallen in die Kasse. Es klappt — du tust es wirklich. Und für einen Moment, über allem Lärm, spürst du einen kleinen, wilden Funken Stolz.",
 36: "Jemand murrt, laut, es sei zu teuer. Ein paar Köpfe drehen sich. Ein Murren kann sich entlang der Reihe ausbreiten oder auf der Stelle sterben, ganz je nachdem, was du als Nächstes tust. Du kannst zurück zum fairen Preis und Frieden halten, oder festbleiben und darauf vertrauen, dass das Essen lauter spricht als eine Stimme.",
 37: "Ein Kunde nimmt einen Bissen und hält inne: „Das ist die echte“, sagt er überrascht. „Wie ihre.“ Er sagt es laut genug, dass andere hören, und ein paar rücken näher. Gutes Essen ist seine beste Werbung — ein glücklicher Mund zieht eine ganze Schlange nach sich.",
 38: "Ein Kunde runzelt die Stirn in die Schale: „Etwas fad“, sagt er. „Nicht wie sonst.“ Vielleicht die billige Ware, vielleicht deine Hand mit dem Ingwer. Schwer zu hören in der ersten Nacht. Du kannst jetzt die Würze richten, vor der nächsten Schale, oder es lassen und hoffen, dass der Andrang es deckt.",
 39: "Zwischen Bestellungen schielst du zur Kasse. Jetzt sind Münzen drin — echte, mit deinen eigenen Händen verdient. Weit von der Summe, noch, aber es ist ein Anfang, und ein Anfang ist weit mehr als das Nichts vor einer Stunde. Du schließt den Deckel und wendest dich wieder Dampf und Menge zu.",
 40: "Du zählst schnell, unter der Theke. Es ist ein Anfang — aber nur das. In diesem Tempo erreichst du die Summe nicht bis zum Morgen; du brauchst den Ansturm, und einen guten. Die große Mitternachtsmenge, hungrig und schnell beim Ausgeben, macht oder bricht eine solche Nacht.",
 41: "Und dann kommt die Menge — kein Rinnsal mehr, sondern eine Welle. Büroleute, Familien, Nachtschichtler, alle auf einmal in die Passage strömend, und der Lärm verdoppelt sich. Zehn Gesichter an der Theke, dann zwanzig. Bestellungen fliegen. Das ist der Ansturm. Das ist die Nacht. Da kommt er.",
 43: "Die Passage ist gestopft voll, Leute drängen mit Taschen und schlafenden Kindern vorbei. Die Luft ist dick und heiß von Dampf und Öl. Dein kleiner Stand ist eine Insel im Lärm. Keine Zeit mehr zum Denken, nur zum Handeln — also holst du Luft und steigst ein.",
 45: "Du wirst zu schnell. Eine Schale geht halb gar hinaus; du gibst zu wenig Wechselgeld, aus Versehen oder nicht. Du sagst dir, es sei der Ansturm, alle machen das. Aber Abkürzungen sind ein Loch im Eimer — sie lassen deinen guten Namen auslaufen, ein kleiner Schnitt nach dem anderen, bis keiner mehr bleibt.",
 46: "Du rufst um Hilfe, die Stimme bricht über dem Lärm. Aber wer kann kommen? Das Marktkind ist nah — flink, immer hungrig, immer bereit für eine Besorgung gegen eine Münze. Oder die Teefrau nebenan, obwohl ein Blick genügt: sie ist genauso überrannt wie du. Eine Sekunde zum Wählen.",
 47: "Der Ansturm rollt weiter und weiter. Arme und Rücken schmerzen — aber die Kasse wird schwerer, und dieser Klang, Münze auf Münze, hält dich. Schale um Schale, Gesicht um Gesicht. Du steckst mittendrin und hältst dich. Du dachtest nicht, dass du es könntest. Und doch bist du hier.",
 48: "„He — das stimmt nicht.“ Der Kunde hält die Hand hin, die Fläche offen: das Wechselgeld fehlt. Ein paar Köpfe drehen sich. Dein Gesicht wird heiß. Das ist der Moment: Du kannst dich entschuldigen und es sofort richten, oder streiten und hoffen, dass er nachgibt, ehe mehr hören.",
 49: "Du siehst die Ware an, und dir sinkt das Herz: Das Schweinefleisch fast weg, das Gemüse bei einer letzten Handvoll. Die Nacht ist nicht halb vorbei, und schon gehst du leer aus. Du kannst kleinere Schalen machen, um zu strecken, nach mehr schicken, oder zusehen, wie der Dämpfer leerläuft und für dich entscheidet.",
 50: "Für einen Moment lichtet sich die Menge, und du atmest. Du wischst Schweiß und Theke. Die Laternen schwanken im Nachtwind. Es wird nicht halten — der echte Mitternachtsansturm steht noch aus — aber eine Pause ist ein Geschenk. Nutz sie gut, und sei bereit, wenn die Welle zurückrollt.",
 51: "„Du hast recht — Verzeihung.“ Du zählst noch einmal, diesmal langsam, und drückst die fehlende Münze in seine Hand. „Lange Nacht. Danke für die Geduld.“ Der Kunde wird milder; die Köpfe drehen sich weg. Ein rasch und freundlich behobener Fehler ist kein Makel — gut gelöst, zählt er sogar ein wenig zu deinen Gunsten.",
 52: "Du stützt dich auf die Theke und atmest eine Sekunde. Die Kasse ist jetzt schwer — schwerer, als du vor einer Stunde zu hoffen wagtest. Du könntest anhalten und zählen, um zu sehen, wie nah du der Summe bist. Oder das Zählen auf später heben und wieder rein, solange die Menge hier ist und Geld ausgibt.",
 54: "„Das Wechselgeld stimmte“, sagst du und hältst seinen Blick, bis er wegsieht. Er zuckt die Schultern und geht murrend davon. Du hast gewonnen — nur eben nicht. Er wird es erzählen, und auf einem Markt reist ein Name schneller als ein Kunde. Du hast heute eine Münze gerettet und etwas weit Wertvolleres ausgegeben.",
 55: "Du drückst dem Kind Münzen in die Hand und schickst es nach mehr Schweinefleisch und Gemüse. Es kennt jeden Hinterweg und ist weg, ehe du den Satz beendest. Jetzt musst du den Stand allein halten, bis es zurück ist. Du hoffst, die Ware reicht, und das Kind ist so schnell und ehrlich, wie du glaubst.",
 56: "Du machst die Schalen etwas kleiner — mehr Brühe, weniger Teigtaschen, ein bisschen weniger Schweinefleisch. Wenige merken es in einer so vollen Nacht. Es streckt die Ware und gewinnt Zeit. Es ist kein Betrug; die Schale bleibt gut, ehrlich und heiß. Nur eine Köchin, die mit dem haushält, was sie hat — die Tante würde nicken.",
 57: "Der Ansturm rollt weiter, und du verlierst darin das Zeitgefühl. Nur Dampf, Gesichter, Schalen, Münzen und die Hitze der Brenner auf den Armen. Draußen wird es spät; irgendwo wartet noch die Summe. Aber jetzt gibt es nur die nächste Schale, und die nächste, und die nächste.",
 59: "In einer Lücke fällt dein Blick aufs hintere Regal. Die beiseitegestellte Schale kühlt langsam aus. Darunter bleibt der Hocker am Ende leer, die ganze Nacht — der von Herrn Behn. Wer ist er? Warum hebt die Tante ihm die Schale auf? Der Ansturm zieht, aber der leere Hocker zieht auch, leiser.",
 60: "Endlich erreicht der Ansturm den Höhepunkt und bricht. Die Menge geht von Welle zu Rinnsal, und du blickst auf, blinzelnd, wie jemand, der aus tiefem Wasser auftaucht. Du stehst noch; der Stand ist noch deiner. Aber die Nacht ist nicht fertig mit dir — in der Ruhe nach der Welle kommt immer etwas.",
 63: "„Nein, danke“, sagst du. „Wir kommen zurecht.“ Soulds Lächeln hält, aber seine Augen werden einen Grad kälter. „Wie du willst“, und er geht zum nächsten Stand. Du fühlst dich leichter, kaum ist er fort. Was auch geschieht heute Nacht, es wird deines sein — der Sieg oder der Verlust, aber niemandes Haken in dir.",
 64: "Du nimmst Soulds Geld. Die Summe ist gedeckt, was die Nacht auch tut. Einen Moment hebt sich das Gewicht und du atmest. Dann kriecht das Unbehagen herauf. Du hast keine Bedingung gelesen; du weißt nicht, was „später“ heißt. Du hast eine Sorge gegen eine andere getauscht — und diese lächelt und weiß, wo sie dich findet.",
 65: "„Was kostet es?“ fragst du. Sould lächelt breiter: „Mach dir darüber jetzt keine Gedanken. Wir regeln das später. Unter Freunden, immer.“ Er nennt keine Zahl, und das ist der ganze Trick. Einen echten Preis wägt man ab; ein Preis ohne Zahl ist ein Seil ohne Ende. Jetzt siehst du es klar.",
 66: "Du betrachtest die Reihe der Standleute, die warten, um Sould zu zahlen. Manche wirken ruhig; andere müde, ein wenig ängstlich. Eine alte Frau zählt ihre Münzen zweimal, ehe sie sie reicht. So funktioniert der Markt wirklich, unter den Laternen: ein stiller Mann, eine lange Schlange, und Geld, das die ganze Nacht zu ihm wandert.",
 67: "Die Standfrau neben dir beugt sich nah: „Was er auch bietet, sag Nein“, murmelt sie. „Sould vergisst nie eine Schuld. Mein Cousin lieh sich einmal. Drei Jahre zahlte er zurück. Drei Jahre.“ Sie richtet sich auf, als Sould herüberblickt. „Sei nur... vorsichtig“, sagt sie und wendet sich ab. Die Warnung liegt kalt in deiner Brust.",
 68: "Kurz vorm Schließen treibt Sould zurück. „Schon die Summe gemacht?“ fragt er sanft, als läge ihm etwas daran. „Denn das Angebot steht noch. Letzte Chance heute Nacht.“ Er weiß genau, wie die Nacht für dich lief — er weiß es immer. Sein Darlehen beendete die Angst sofort. Aber sein Darlehen endet nie wirklich.",
 74: "Du reichst dem Kind eine volle Schale: „Iss. Du hast es dir verdient.“ Sein ganzes Gesicht verändert sich. Es isst schnell, in einer Ecke, als fürchtete es, es könnte verschwinden. Es ist eine Schale; sie kostet dich fast nichts. Aber für das Kind ist sie einen Moment die ganze Welt — und es vergisst nicht, wer sie ihm gab.",
 75: "Du bezahlst das Kind in Münzen, wie vereinbart, nicht mehr. Es steckt sie ein und nickt — es versteht; Münzen sind der Deal, und der Deal ist fair. Aber es ist noch hungrig und schielt zu den Schalen, als es geht. Du warst fair. Fair ist in Ordnung. Aber fair ist nicht ganz dasselbe wie gütig.",
 76: "Das Kind geht nicht. Es lungert am Rand des Stands — schaut, lernt, reicht ein Tuch oder einen Löffel, ehe du fragst. Es in der Nähe zu haben, macht die ganze Nacht leichter. Ein Markt ist voll von Menschen, die durch die Ritzen fallen, und manchmal ist ein Stand der eine warme Ort, der sie bleiben lässt.",
 77: "Zwischen Schalen nennt dir das Kind seinen Namen. Und wo es schläft — eine trockene Ecke hinter dem Fischbogen, meist. Es sagt es schlicht, ohne Mitleid zu suchen. Du hörst zu und merkst es dir. Ein Name ist klein zu geben und groß zu halten, und der Markt fühlt sich ein wenig weniger fremd an.",
 78: "Du lässt das Kind den Stand hüten, während du nach hinten für mehr Ware schlüpfst. Ein kleines Vertrauen, das es ernst nimmt — aufrecht, Kunden zum Warten winkend, die Kasse mit beiden Augen bewachend. Als du zurückkommst, fehlt nichts. Vertrauen gegeben, Vertrauen gehalten — und das zählt, an einem Ort wie diesem.",
 79: "Regen fegt durch die Passage, plötzlich und hart, trommelnd auf die Dächer. Die Menge zerstreut sich ins Trockene, und deine Theke leert sich in Sekunden. Regen kann eine Verkaufsnacht töten. Oder, richtig genutzt, deinen Stand mit kalten, nassen Leuten füllen, die plötzlich etwas Heißes wollen. Es liegt an dir.",
 80: "Du prüfst die Töpfe. Die Brühe ist niedrig, die Ware fast fertig — genug für eine Weile, nicht für die ganze Nacht. Jetzt musst du wählen, wie du den Rest ausgibst. Kleine, sorgsame Schalen, um bis zum Morgen zu reichen. Oder volle, großzügige Schalen jetzt, auf die Gefahr, Stunden zu früh leerzulaufen.",
 81: "Du ziehst die Markise herunter und wartest es ab. Der Regen läuft in einer langen silbernen Linie ab. Eine Weile kommt fast niemand, also nutzt du die Zeit — wischen, auffüllen, die müden Füße rasten, die Brühe probieren. Regen vergeht am Ende immer. Und dann kommt der Markt wieder heraus, kalt und hungrig, und du bist bereit und warm.",
 82: "Du rufst in den Regen: „Heiße Schalen! Raus aus der Nässe!“ Ein paar Durchnässte ducken sich dankbar unter die Markise. Du verkaufst ihnen kleinere, billigere Schalen, schnell und heiß. Weniger Geld pro Schale. Aber ein voller Stand zieht mehr Leute als ein leerer, und Wärme verkauft sich selbst in einer kalten, nassen Nacht.",
 83: "Der große Topf ist fast leer — man sieht den Boden unter der letzten Brühe. Das ist der wahre Gefahrenpunkt der Nacht. Zu früh leer, und du stehst vor einem kalten, geschlossenen Stand, während der Markt sich noch bewegt. Du kannst den letzten Rest strecken oder akzeptieren, dass der Topf fertig ist, und zählen.",
 84: "Du streckst die letzte Brühe — ein wenig mehr Wasser, eine vorsichtige Hand mit der Würze, kleine Schalen zu kleinen Preisen. Sie ist dünner als das Beste der Tante, du weißt es. Aber noch heiß, ehrlich und in der Form ihre. Lieber eine kleine echte Schale als keine — also hältst du Laterne und Topf noch eine Weile.",
 85: "Die Nacht wendet sich jetzt. Die Menge lichtet sich, der Lärm wird sanfter, und der Markt beginnt sein langsames Gleiten zum Morgen. Stände weiter unten ziehen schon die Gitter herunter. Bald kommt der Meister für die Gebühren. Du spürst die ganze lange Nacht in Armen und Rücken — aber fast ist es vorbei, und fast hast du es geschafft, so oder so.",
 86: "Ein neuer Stand öffnet direkt gegenüber, zum halben Preis. Der Besitzer ruft laut, winkt Leute heran, und ein Teil deiner Schlange treibt zu ihm. Billig und laut zieht schnell eine Menge, in einer solchen Nacht. Du kannst den Preis senken und kämpfen — oder deinen Preis halten und darauf vertrauen, dass dein Essen deine Leute hält.",
 87: "Du senkst den Preis, um gleichzuziehen, und steckst in einem Preiskrieg. Schalen fliegen hinaus, aber jede bringt fast nichts. Überrannt kommst du nicht voran. Es ist ein Wettlauf nach unten, und der Boden ist, wo Stände für immer schließen. Eine Nacht gewinnt man nicht allein über den Preis — du brauchst einen anderen Weg, schnell.",
 88: "Du verlässt deine eigene Theke und gehst gerade zu ihr. Gemeinsam richtet ihr den Kessel auf, wischt den heißen Tee weg, beruhigt ihre verärgerten Kunden und bringt sie wieder in Gang. Es kostet dich ein paar Minuten und ein paar Verkäufe. Sie packt deinen Arm, atemlos: „Das vergesse ich nicht.“ Und an dieser Ecke sind das nicht nur Worte.",
 89: "Du hältst deinen Preis und lässt den billigen Stand sich heiser schreien. Manche treiben zu ihm, sicher. Aber deine Stammgäste bleiben. „Seins ist Wasser“, sagt einer und nickt zu deinem Topf. „Deins ist das Echte.“ Gutes Essen gewinnt eine Nacht langsamer, aber sicherer. Du bist nicht der billigste Stand — du bist der, für den man ansteht.",
 90: "In den frühen Stunden erlischt der billige Stand gegenüber. Er verkaufte alles viel zu billig, verdiente fast nichts und ging Ware und Mut zugleich aus. Der Besitzer packt zusammen, müde und verdrossen. Deine Laterne brennt noch, dein Topf ist noch warm. Langsam, stetig und ehrlich überdauert laut und billig, meist.",
 91: "Das Schließen ist nah. Die Menge ist dünn, der Lärm leise. Im Regal wartet die beiseitegestellte Schale noch — kalt inzwischen, aber da. Darunter ist der Hocker am Ende noch leer. Jeden Moment kommt der Meister. Aber deine Augen wandern immer wieder zu diesem Hocker, zur kalten Schale, und zur Frage, die nie beantwortet wurde.",
 92: "Sould erscheint an deiner Theke, pünktlich: „Nun? Schon die Summe gemacht? Oder brauchst du doch das kleine Darlehen?“ Wenn du zu kurz bist, ist das der leichte Ausweg: sein Geld nehmen, den Meister zahlen, die Ecke heute Nacht halten. Aber du kennst nun den wahren Preis seiner Hilfe. Du musst ihm antworten.",
 93: "Ein alter Mann kommt langsam durch die sich lichtende Menge — mager, grau, müde. Er hält am leeren Hocker am Ende und legt eine Hand darauf, als kennte er ihn gut. Er sieht dich an, dann das Regal, dann weg. Er setzt sich nicht. Er bestellt nicht. Er steht nur da und wartet auf etwas, das du nicht benennen kannst.",
 94: "Du nimmst die beiseitegestellte Schale herunter und stellst sie vor ihn: „Die ist Ihre. Das war sie immer.“ Der alte Mann sieht die Schale an, dann dich, und seine Augen füllen sich. „Sie hat sie aufgehoben“, sagt er ganz leise. „All die Zeit. Sie hat sie aufgehoben.“ Du verstehst noch nicht alles — aber du weißt, du hast etwas Richtiges getan.",
 95: "Du bedienst ihn, und endlich setzt er sich. Während er isst, spricht er ein wenig. Er und die Tante waren einst nah — dann ein Zerwürfnis, klein und töricht, von der Art, die mit den Jahren erhärtet. Er hörte auf zu kommen. Aber er hörte nie auf, es zu wollen. „Sag es ihr“, flüstert er. „Sag ihr, Behn ist zurück.“",
 96: "Der Hocker am Ende stand die ganze Nacht leer, während sich jeder andere Platz füllte und leerte und wieder füllte. Ein leerer Hocker, eine kalte, beiseitegestellte Schale im Regal darüber. Es ist das Stillste auf einem lauten Markt — und, wenn du hinhörst, das Lauteste. Die Tante hebt ihn aus einem Grund auf. Du wüsstest gern, warum.",
 97: "Du denkst an das Gesicht der Tante am Telefon — wie ihre Stimme beim Namen Behn kippte. Nicht Zorn. Etwas Weicheres und Traurigeres. Wer er auch ist, er bedeutet ihr noch etwas, nach all den Jahren. Die Schale im Regal ist nicht nur Gewohnheit. Es ist eine Tür, die sie offen hält, für alle Fälle. So viel verstehst du jetzt zumindest.",
 98: "Neben der Kasse, halb verborgen, liegt ein altes Foto. Du bist die ganze Nacht daran vorbeigegangen, ohne hinzusehen. Jetzt tust du es: die Tante, viel jünger, lachend. Neben ihr ein junger Mann, der auch lacht. Auf der Rückseite, in ihrer Schrift, zwei Worte: ich und Behn. Der leere Hocker und die kalte Schale ergeben plötzlich Sinn.",
 100: "Während Behn isst, beginnst du zu verstehen, was diese Nacht wirklich geworden ist. Es ging nie nur um die Summe. Die Tante schickte dich, den Stand zu führen — aber auch, ohne es je zu sagen, ihre Tür offen zu halten. Und es hat geklappt: er kam zurück. Was auch mit dem Geld geschieht, dieser Teil der Nacht ist schon ein Sieg.",
 101: "Schließzeit. Du ziehst die Kasse hervor und zählst, Münze um Münze, im tiefen Laternenlicht. Dein Herz schlägt hart. Ist es genug? Die Zahl steigt, während du zählst, und du zählst noch einmal zur Sicherheit. Entlang der Reihe hörst du den Meister kommen — Stand um Stand, die Gebühren nehmend, eine Tür nach der anderen. Du bist bald dran.",
 102: "Der Meister geht die Reihe hinunter, langsam und sicher. Alt, gerecht, hat er in dreißig Jahren jeden Trick eines Stands gesehen. An jedem Platz hält er, nimmt die Gebühr, trägt ins Buch ein und geht weiter. Manche zahlen leicht; manche können nicht. Du siehst ihn näher kommen und hältst deine Kasse ein wenig fester.",
 103: "Du siehst einen Stand weiter unten zu kurz kommen. Der Meister schüttelt den Kopf, fest, aber nicht hart. Der Standmann beginnt, langsam, zusammenzupacken — Teller, Töpfe, ein ganzes Leben voller Nächte, in Kisten verstaut. Kein Geschrei, nur ein stilles Ende. Das könntest du in einer Stunde sein. Der Gedanke gibt dir Stahl: nicht heute Nacht, nicht die Ecke der Tante.",
 104: "Eine nach der anderen, die ganze Reihe entlang, kommen die Laternen herunter. Der Markt bringt sich zu Bett. Die helle, laute Welt von vor ein paar Stunden faltet sich in Kisten und Schatten. Deine zwei roten Laternen leuchten noch, vorerst. Ob sie nächste Saison hier hängen, entscheidet sich in den nächsten Minuten — und in den Münzen deiner Kasse.",
 105: "Graues Licht kriecht über die Marktdächer: der Morgen, das Ende der Nacht und das Ende der Saison. Irgendwo hebt ein einsamer Vogel an. Die Luft riecht nach kalter Asche und altem Dampf. Du stehst die ganze Nacht auf den Beinen, und du spürst jede Stunde. Aber du bist noch hier, und der Stand ist noch deiner — vorerst.",
 110: "Der Meister hält am Stand 24. Er sieht dich an, dann den Stand, dann den leeren Platz der Tante. „Also du bist es heute Nacht“, sagt er. „Wie lief's?“ Das ist es: die ganze Nacht auf einen Augenblick und eine Zahl zusammengeschrumpft. Du atmest und öffnest die Kasse. Alles, was du heute Nacht getan hast, liegt da drin.",
 111: "Du zählst es vor ihm aus, Münze um Münze. Die ganze Nacht liegt im Geld — die guten Schalen, die harten Entscheidungen, die Ecken gehalten oder geschnitten. Der Meister sieht zu, geduldig, sagt gar nichts. Du bist nah an der Summe. Nah. Aber „nah“ kann im Morgengrauen nach beiden Seiten kippen, und alles hängt an diesem letzten Zählen.",
 112: "Die Zählung endet knapp darunter. Nicht um viel — aber zu kurz ist zu kurz, und das Buch des Meisters rundet für niemanden auf. Die Ecke entgleitet dir, fehlende Münze um fehlende Münze. Es sei denn — vielleicht bleibt noch eine Karte oder zwei zu spielen, wenn du den Rest der Nacht gut geführt hast. Du denkst schnell: Was hast du, das das Geld allein nicht zeigt?",
 113: "Du bist beim allerletzten Mittel. Das Geld fehlt, der Vermittler hat abgelehnt, die Teefrau ist schon am Limit. Es bleibt das Kleinere, Stillere — eine Freundlichkeit von vorhin vielleicht, die zurückkommt. Oder gar nichts. Manchmal geht eine Nacht einfach nicht auf, so hart du sie auch bearbeitet hast. Du wartest ab, welche Art Nacht es wird.",
 114: "Es bleibt nichts, das du der Gebühr entgegensetzen könntest. Nicht genug Geld, kein geschuldeter Gefallen, keine Freundlichkeit, die zurückkehrt. Nur du, eine kalte Kiste voll Münzen und eine Zahl, die du nicht ganz erreichen konntest. Der Meister wartet auf deine Antwort, nicht unfreundlich. Wie es auch endet, du hast die ganze Nacht dafür gearbeitet — und das muss zählen, auch wenn nicht heute.",
}
def main():
    data=json.load(open(OUT,encoding="utf-8")); a=0
    for nid,t in G.items():
        k=str(nid)
        if k not in data: data[k]=t; a+=1
    data={k:data[k] for k in sorted(data,key=lambda x:int(x))}
    json.dump(data,open(OUT,"w",encoding="utf-8"),ensure_ascii=False,indent=1)
    print(f"the-night-market/de.json: {len(data)} (+{a})")
if __name__=="__main__": main()
